(()=>{const hero=document.querySelector('.hero-yarn'),svg=hero.querySelector('.yarn-drawing'),path=svg.querySelector('path');function draw(){const h=hero.getBoundingClientRect(),w=hero.querySelector('.write-word').getBoundingClientRect(),p=hero.querySelector('.portrait').getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${h.width} ${h.height}`);const startX=w.right-h.left+5,startY=w.top-h.top+w.height*.55,endX=p.left-h.left+30;const space=Math.max(30,endX-startX),cx=startX+space*.5,cy=startY,rx=Math.min(60,space*.45),ry=40;let d=`M${startX} ${startY}`;const loops=18,points=loops*28;for(let i=0;i<=points;i++){const t=i/points*Math.PI*2*loops;const x=cx+rx*(.66*Math.cos(t)+.24*Math.cos(t*.29));const y=cy+ry*(.72*Math.sin(t)+.2*Math.sin(t*.37));d+=` L${x.toFixed(2)} ${y.toFixed(2)}`;}d+=` C${cx+rx} ${cy+ry} ${endX-30} ${cy+30} ${endX} ${p.top-h.top+p.height*.6}`;path.setAttribute('d',d)}document.fonts.ready.then(draw);window.addEventListener('resize',draw)})();